export function translateGerman(value) {
  if (typeof value !== 'string' || !value.trim()) return value;
  const text = value.trim();
  const imageText = translateImageText(value, 'de');
  if (imageText !== value) return imageText;
  const pad = (result) => value.replace(text, result);
  if (Object.hasOwn(de, text)) return pad(de[text]);
  const t = translateGerman;
  const weightWarning = ' Removed parts exceed the whole-bike weight; check units and avoid counting removed components twice.';
  if (text.endsWith(weightWarning)) return pad(`${t(text.slice(0, -weightWarning.length))} ${t(weightWarning.trim())}`);
  const patterns = [
    [/^Conditional price; enter your eligible checkout quote\. (.+) · (.+) · (.+)$/, (_, condition, amount, date) => `Bedingter Preis; den tatsächlich berechtigten Checkout-Preis eingeben. ${t(condition)} · ${amount} · ${date}`],
    [/^Category: (.+)\.$/, (_, label) => `Kategorie: ${t(label)}.`],
    [/^Up to (.+) rear$/, (_, amount) => `Bis ${amount} hinten`],
    [/^(.+) total remaining-build allowance in yuan$/, (_, plan) => `${t(plan)}: Gesamtzuschlag für den Restaufbau in Yuan`],
    [/^(.+) plan: (¥[\d,]+) total build allowance\. (.+)\.$/, (_, plan, price, basis) => `${plan}-Plan: ${price} Gesamtzuschlag für den Aufbau. ${t(basis.replace(/\.+$/, ''))}.`],
    [/^(.+) plan: enter the total remaining-build allowance\. (.+)\.$/, (_, plan, basis) => `${plan}-Plan: Gesamtzuschlag für den Restaufbau eingeben. ${t(basis.replace(/\.+$/, ''))}.`],
    [/^(.+) known \+ (\d+) unknown$/, (_, amount, count) => `${amount} bekannt + ${count} unbekannt`],
    [/^(.+) (base \/ known deltas|known) \+ (\d+) unknown$/, (_, amount, basis, count) => `${amount} ${basis === 'known' ? 'bekannt' : 'Basis / bekannte Änderungen'} + ${count} unbekannt`],
    [/^(Purchase total|Complete price) needs (\d+) more inputs?; (projected weight|complete weight) needs (\d+) more inputs?\.$/, (_, kind, prices, weight, weights) => `${kind === 'Purchase total' ? 'Gesamter Kaufpreis' : 'Gesamtpreis'}: ${prices} fehlende Eingaben; ${weight === 'projected weight' ? 'erwartetes Gewicht' : 'Gesamtgewicht'}: ${weights} fehlende Eingaben.`],
    [/^Included in (.+); not counted again\.$/, (_, name) => `In ${name} enthalten; nicht erneut gezählt.`],
    [/^(.+) does not list (.+) frame compatibility\.$/, (_, name, standard) => `${name}: keine dokumentierte Kompatibilität mit ${standard}-Rahmen.`],
    [/^Confirm drivetrain: tire limits are (.+)\/(.+) mm \(1×\/2×\)\. Choose a known layout before using these limits; an unknown layout has no confirmed maximum\.$/, (_, single, double) => `Antrieb bestätigen: Reifengrenzen ${t(single)}/${t(double)} mm (1×/2×). Vor Anwendung dieser Grenzen die Anordnung wählen; bei unbekannter Anordnung ist kein Maximum bestätigt.`],
    [/^(.+) mm tires exceed the frame's published (.+) mm limit( for (?:1×|2×))?\.$/, (_, width, limit, layout) => `${width}-mm-Reifen überschreiten die veröffentlichte Rahmengrenze ${limit} mm${layout ? ` bei ${layout.slice(5)}` : ''}.`],
    [/^Rotors use (.+), but the wheelset lists (.+); confirm a compatible rotor or explicitly supported adapter\.$/, (_, rotor, hub) => `Bremsscheiben nutzen ${rotor}, Laufräder ${hub}. Passende Scheibe oder ausdrücklich unterstützten Adapter bestätigen.`],
    [/^(.+) requires (.+); the selected wheelset does not list it\.$/, (_, name, hub) => `${name} benötigt ${hub}; für die gewählten Laufräder nicht dokumentiert.`],
    [/^for (.+)$/, (_, name) => `für ${name}`],
    [/^Category-specific facts are comparable across these (\d+) selections\.$/, (_, count) => `Kategoriespezifische Angaben sind zwischen diesen ${count} Modellen vergleichbar.`],
    [/^selected · (\d+)-bike limit reached$/, (_, count) => `ausgewählt · Höchstzahl ${count} Räder erreicht`],
    [/^Reorder (.+)$/, (_, name) => `${name}: Reihenfolge ändern`],
    [/^Product image © (.+)$/, (_, owner) => `Produktfoto © ${owner}`],
    [/^View (\d+)(?: \((\d+) of (\d+)\))?$/, (_, view, index, count) => `Ansicht ${view}${index ? ` (${index} von ${count})` : ''}`],
    [/^(.+) \((\d+) of (\d+)\)$/, (_, label, index, count) => `${t(label)} (${index} von ${count})`],
    [/^Show (.+) — (.+)$/, (_, label, accuracy) => `${t(label)} zeigen — ${t(accuracy)}`],
    [/^product image (\d+)$/, (_, n) => `Produktfoto ${n}`],
    [/^Evidence reviewed (.+)$/, (_, date) => `Belege geprüft ${date}`],
    [/^Current reference(?: · (.+))?$/, (_, date) => `Aktueller Referenzbeleg${date ? ` · ${date}` : ''}`],
    [/^Dated mainland China observation(?: · (.+))?$/, (_, date) => `Datierte Beobachtung in Festlandchina${date ? ` · ${date}` : ''}`],
    [/^Product facts: (.+?)(?: · Price: (.+?))?(?: · Image: (.+?))? · accessed (.+)$/, (_, facts, price, image, date) => `Produktfakten: ${t(facts)}${price ? ` · Preis: ${t(price)}` : ''}${image ? ` · Bild: ${t(image)}` : ''} · abgerufen ${date}`],
    [/^Frame (¥.+)$/, (_, price) => `Rahmen ${price}`],
    [/^Up to (.+)$/, (_, amount) => `Bis ${amount}`],
    [/^(.+) — price & specifications$/, (_, name) => `${t(name)} — Preis und Spezifikationen`],
    [/^(.+) — (frameset|bike build) research$/, (_, name, kind) => `${t(name)} — ${kind === 'frameset' ? 'Rahmenset' : 'Ausstattung'}: Recherche`],
    [/^(.+) bikes in China$/, (_, name) => `${name}: Fahrräder in China`],
    [/^(.+) publication-ready complete bikes and framesets documented for riders in China, with dated prices and model-level sources\.$/, (_, name) => `${name}: dokumentierte Kompletträder und Rahmensets für China mit datierten Preisen und Modellquellen.`],
    [/^Select (.+) for comparison$/, (_, name) => `${t(name)} zum Vergleich wählen`],
    [/^View (.+) details$/, (_, name) => `${t(name)}: Details ansehen`],
    [/^Filter (.+)$/, (_, name) => `${t(name[0].toUpperCase() + name.slice(1))} filtern`],
    [/^(.+) — show this brand in the catalog$/, (_, name) => `${name} — diese Marke im Katalog zeigen`],
    [/^(\d+) matches$/, (_, n) => `${n} Treffer`],
    [/^(\d+) systems · reviewed (.+)$/, (_, n, date) => `${n} Systeme · geprüft ${date}`],
    [/^Est\. (.+)$/, (_, amount) => `Geschätzt ${amount}`],
    [/^(.+) details$/, (_, name) => `${t(name)}: Details`],
    [/^About (.+)$/, (_, name) => `Über ${name}`],
    [/^Visit the official (.+) website$/, (_, name) => `Offizielle ${name}-Website besuchen`],
    [/^(.+) frameset( package)?$/, (_, name, packageWord) => `${name} ${packageWord ? 'Rahmensetpaket' : 'Rahmenset'}`],
    [/^(.+) (frame|complete bike|fitted|stock)$/, (_, before, kind) => `${before} ${t(kind)}`],
    [/^(.+) tire clearance$/, (_, width) => `${width} Reifenfreiheit`],
    [/^What defines the (.+)$/, (_, name) => `Was ${name} auszeichnet`],
    [/^What is verified about the (.+)$/, (_, name) => `Belegte Angaben zu ${name}`],
    [/^The recorded complete-bike price is (.+); the dated price record below preserves its channel and conditions\.$/, (_, price) => `Der dokumentierte Komplettradpreis ist ${price}; die Preisbelege unten bewahren Kaufkanal und Bedingungen.`],
    [/^The recorded complete-bike price is (.+); its date and basis remain visible below\.$/, (_, price) => `Dokumentierter Komplettradpreis: ${price}; Datum und Grundlage stehen unten.`],
    [/^The displayed (.+) estimate adds the adjustable (.+) build allowance to the latest frame price\.$/, (_, price, allowance) => `Die angezeigte Schätzung ${t(price)} addiert den anpassbaren Aufbauzuschlag ${allowance} zum letzten Rahmenpreis.`],
    [/^This version is no longer sold new and was superseded by the (.+)\. The dated price record below is historical only\.$/, (_, name) => `Diese Version wird nicht mehr neu verkauft und wurde durch ${name} abgelöst. Der Preisbeleg unten ist ausschließlich historisch.`],
    [/^(.+) (frame|complete bike) with (.+) tire clearance$/, (_, weight, kind, width) => `${weight} ${t(kind)} mit ${width} Reifenfreiheit`],
    [/^(.+) · (Observed|Promo|Official|Research|Available|Historical|Component|Approx\.|Promo-conditional)$/, (_, before, kind) => `${t(before)} · ${t(kind)}`],
    [/^(Theme): (System|Light|Dark)(?:\. Switch to (system|light|dark) theme)?$/, (_, label, mode, next) => `Farbschema: ${t(mode)}${next ? `. Zu ${t(next[0].toUpperCase() + next.slice(1))} wechseln` : ''}`],
    [/^The groupset alone leaves (.+) of the (.+) allowance for every other missing item\. This is an incomplete cost sketch, not a ready-to-order or compatibility-checked build\.$/, (_, rest, amount) => `Nach der Schaltgruppe bleiben ${rest} vom Zuschlag ${amount} für alle anderen fehlenden Positionen. Dies ist ein unvollständiges Kostenbeispiel, kein bestellfertiger oder auf Kompatibilität geprüfter Aufbau.`],
    [/^Frame package (.+)$/, (_, price) => `Rahmenpaket ${t(price)}`],
    [/^(.+) shown$/, (_, name) => `${name} gezeigt`],
    [/^View the official (.+) product page$/, (_, name) => `Offizielle ${name}-Produktseite ansehen`],
    [/^(.+) weight$/, (_, weight) => `${t(weight)} Gewicht`],
    [/^tire clearance (.+)$/, (_, width) => `Reifenfreiheit ${width}`],
    [/^Superseded by (.+)$/, (_, name) => `Abgelöst durch ${name}`],
    [/^(.+) — (\d+) selected$/, (_, name, n) => `${name} — ${n} ausgewählt`],
    [/^Move (.+) (left|right)$/, (_, name, side) => `${name} nach ${side === 'left' ? 'links' : 'rechts'}`],
    [/^Remove (.+)$/, (_, name) => `${name} entfernen`],
    [/^Remove (.+) from comparison$/, (_, name) => `${name} aus dem Vergleich entfernen`]
  ];
  for (const [pattern, replacement] of patterns) if (pattern.test(text)) return pad(text.replace(pattern, replacement));
  if (text.startsWith('· ')) return pad(`· ${t(text.slice(2))}`);
  if (text.includes(' · ')) return pad(text.split(' · ').map(t).join(' · '));
  return value;
}

